solution.solution.cpp:
#include <string>
#include <vector>

// The most frames on the stack at once, or -1 if a return happens with nothing to return from.
int maxDepth(const std::vector<std::string>& events)
{
    int depth{ 0 };
    int deepest{ 0 };
    for (const std::string& event : events)
    {
        if (event == "call")
        {
            ++depth;
            if (depth > deepest) deepest = depth;
        }
        else if (event == "return")
        {
            if (depth == 0) return -1;
            --depth;
        }
    }
    return deepest;
}

unitTests:
TEST("no events") { CHECK_EQ(maxDepth({}), 0); }
TEST("one call") { CHECK_EQ(maxDepth({ "call", "return" }), 1); }
TEST("nested calls") { CHECK_EQ(maxDepth({ "call", "call", "call", "return", "return", "return" }), 3); }
TEST("calls one after another") { CHECK_EQ(maxDepth({ "call", "return", "call", "return", "call", "return" }), 1); }
TEST("the example") { CHECK_EQ(maxDepth({ "call", "call", "return", "call", "call", "return", "return", "return" }), 3); }
TEST("a return with nothing to return from") { CHECK_EQ(maxDepth({ "call", "return", "return" }), -1); }
TEST("still running at the end") { CHECK_EQ(maxDepth({ "call", "call" }), 2); }

